# ConceptARC DSL program (the verifier is this descriptor, run by the interpreter below):
# {"action": {"color": {"op": "selector_color","selector": {"min_span_ratio": 0.5,"op": "spanning_line","orientation": "horizontal"}},"op": "recolor_cells"},"selector": {"op": "union","selectors": [{"axis": "col","mode": "min","object_selector": {"candidate_selector": {"of": {"min_length": 2,"op": "line_segments"},"op": "all"},"comparison": "strict_bbox","exclude_reference": true,"op": "objects_relative_to_reference","reference_selector": {"min_span_ratio": 0.5,"op": "spanning_line","orientation": "horizontal"},"relation": "above"},"op": "object_extreme_cells"},{"axis": "col","mode": "max","object_selector": {"candidate_selector": {"of": {"min_length": 2,"op": "line_segments"},"op": "all"},"comparison": "strict_bbox","exclude_reference": true,"op": "objects_relative_to_reference","reference_selector": {"min_span_ratio": 0.5,"op": "spanning_line","orientation": "horizontal"},"relation": "below"},"op": "object_extreme_cells"}]}}
# Entry point: output = transform_dsl_program(program, input_grid)

# --- action: how the selection is turned into the output grid ---

def transform_dsl_program(program: DslProgram, grid: Grid) -> Grid:
    # Dispatch trimmed to the branch(es) this program uses.
    """Apply a default DSL program to an input grid.

    Args:
      program (DslProgram): DSL program.
      grid (Grid): Input grid.

    Returns:
      Grid: Output grid.
    """
    selection = select_scene_objects(program.selector, grid)
    action_op = program.action.get("op")
    if action_op == "recolor_cells":
        return recolor_cells(
            grid,
            expect_cell_group(selection),
            resolve_color_expression(program.action["color"], grid),
        )

# --- selection: which cells/objects the program operates on ---

def select_scene_objects(selector: dict[str, Any], grid: Grid) -> SceneSelection:
    # Dispatch trimmed to the branch(es) this program uses.
    """Select object(s) from a grid using a DSL selector expression.

    Args:
      selector (dict[str, Any]): Selector expression.
      grid (Grid): Input grid.

    Returns:
      SceneSelection: Selected object or object pair.
    """
    op = selector.get("op")
    if op == "union":
        return _union_selection(selector, grid)
    if op == "object_extreme_cells":
        return object_extreme_cells(
            grid,
            selector["object_selector"],
            str(selector.get("axis", "col")),
            str(selector.get("mode", "min")),
            bool(selector.get("allow_empty", False)),
        )

# --- helpers the branches above reach (ConceptARC-GEN, verify side only; `common.grid(w, h, c)` is ARC-GEN's blank-grid constructor) ---

Grid = list[list[int]]

Pixel = tuple[int, int]

Bounds = tuple[int, int, int, int]

def bounds(pixels: Sequence[Pixel]) -> Bounds:
    """Return row/column bounds for pixels.

    Args:
      pixels (Sequence[Pixel]): Pixels to bound.

    Returns:
      Bounds: ``min_row, min_col, max_row, max_col``.
    """
    rows = [row for row, _ in pixels]
    cols = [col for _, col in pixels]
    return (min(rows), min(cols), max(rows), max(cols))

SceneSelection = Union[SceneCell, SceneCellGroup, SceneCellPatch, SceneCount, SceneRowRun, SceneObject, tuple[SceneObject, SceneObject], SceneObjectGroup, SceneObjectReferenceGroup, SceneShapeInstance, SceneShapeInstanceGroup]

def object_bounds(obj: SceneObject) -> tuple[int, int, int, int]:
    """Return object bounds.

    Args:
      obj (SceneObject): Object to inspect.

    Returns:
      tuple[int, int, int, int]: ``min_row, min_col, max_row, max_col``.
    """
    return bounds(obj.pixels)

def object_extreme_cells(grid: Grid, object_selector: dict[str, Any], axis: str, mode: str, allow_empty: bool=False) -> SceneCellGroup:
    """Return object cells lying on an extreme row or column.

    Args:
      grid (Grid): Grid to inspect.
      object_selector (dict[str, Any]): Selector naming one or more objects.
      axis (str): Either ``"row"`` or ``"col"``.
      mode (str): ``"min"`` selects topmost/leftmost cells; ``"max"`` selects
          bottommost/rightmost cells.
      allow_empty (bool): Whether an empty result is meaningful.

    Returns:
      SceneCellGroup: Selected extreme cells.
    """
    if axis not in {'row', 'col'}:
        raise ValueError('object_extreme_cells axis is unsupported')
    if mode not in {'min', 'max'}:
        raise ValueError('object_extreme_cells mode is unsupported')
    objects = _container_selection_objects(select_scene_objects(object_selector, grid))
    axis_index = 0 if axis == 'row' else 1
    cells = [pixel for obj in objects for pixel in obj.pixels if pixel[axis_index] == _position_extreme_key(obj, axis, mode)]
    if not cells and (not allow_empty):
        raise ValueError('object_extreme_cells selector found no cells')
    return SceneCellGroup(tuple(sorted(set(cells))))

def _position_extreme_key(obj: SceneObject, axis: str, mode: str, basis: str='edge') -> int | float:
    """Return a position key for an object's extreme edge.

    Args:
      obj (SceneObject): Candidate scene object.
      axis (str): Either ``"row"`` or ``"col"``.
      mode (str): Either ``"min"`` or ``"max"``.
      basis (str): Bounding-box edge or center comparison basis.

    Returns:
      int | float: Grid coordinate for the requested positional basis.
    """
    min_row, min_col, max_row, max_col = object_bounds(obj)
    return min_col if mode == 'min' else max_col

def _selection_is_empty(selection: SceneSelection) -> bool:
    """Return whether a selection has no selected elements.

    Args:
      selection (SceneSelection): Selection to inspect.

    Returns:
      bool: Whether the selection is empty.
    """
    if isinstance(selection, SceneCellGroup):
        return not selection.cells
    if isinstance(selection, SceneObjectGroup):
        return not selection.objects
    if isinstance(selection, SceneObjectReferenceGroup):
        return not selection.pairs
    return False

def _union_selection(selector: dict[str, Any], grid: Grid) -> SceneObjectGroup | SceneCellGroup:
    """Return the union of several object-group or cell-group selectors.

    Args:
      selector (dict[str, Any]): Union selector expression.
      grid (Grid): Input grid.

    Returns:
      SceneObjectGroup | SceneCellGroup: Ordered, de-duplicated selected items.
    """
    selectors = selector.get('selectors', [])
    if not isinstance(selectors, list) or not selectors:
        raise ValueError('union selector requires a non-empty selector list')
    selections = []
    for child_selector in selectors:
        if not isinstance(child_selector, dict):
            raise ValueError('union selector entries must be dictionaries')
        selections.append(select_scene_objects(child_selector, grid))
    if all((isinstance(selection, (SceneCell, SceneCellGroup)) for selection in selections)):
        result: SceneObjectGroup | SceneCellGroup = _union_cell_selections(selections)
    elif all((isinstance(selection, (SceneObject, SceneObjectGroup, tuple)) for selection in selections)):
        result = _union_object_selections(selections)
    else:
        raise ValueError('union selector cannot mix object and cell selections')
    if _selection_is_empty(result) and (not bool(selector.get('allow_empty', False))):
        raise ValueError('union selector found no selected items')
    return result

def _union_object_selections(selections: list[SceneSelection]) -> SceneObjectGroup:
    """Return the object-union of selector results.

    Args:
      selections (list[SceneSelection]): Object selections to combine.

    Returns:
      SceneObjectGroup: Ordered, de-duplicated selected objects.
    """
    objects: list[SceneObject] = []
    seen: set[SceneObject] = set()
    for selection in selections:
        for obj in _container_selection_objects(selection):
            if obj in seen:
                continue
            objects.append(obj)
            seen.add(obj)
    return SceneObjectGroup(tuple(objects))

def _union_cell_selections(selections: list[SceneSelection]) -> SceneCellGroup:
    """Return the cell-union of selector results.

    Args:
      selections (list[SceneSelection]): Cell selections to combine.

    Returns:
      SceneCellGroup: Ordered, de-duplicated selected cells.
    """
    cells: list[Pixel] = []
    seen: set[Pixel] = set()
    for selection in selections:
        selected_cells = expect_cell_group(selection).cells
        for cell in selected_cells:
            if cell in seen:
                continue
            cells.append(cell)
            seen.add(cell)
    return SceneCellGroup(tuple(cells))

def expect_cell_group(selection: SceneSelection | None) -> SceneCellGroup:
    """Return a selected cell group or raise a type error.

    Args:
      selection (SceneSelection | None): Selection to validate.

    Returns:
      SceneCellGroup: Selected cell group.
    """
    if isinstance(selection, SceneCellGroup):
        return selection
    if isinstance(selection, SceneCell):
        return SceneCellGroup(((selection.row, selection.col),))
    raise ValueError('DSL action requires a cell-group selection')

def _container_selection_objects(selection: SceneSelection) -> tuple[SceneObject, ...]:
    """Return selected objects suitable for container-region construction.

    Args:
      selection (SceneSelection): Selector result.

    Returns:
      tuple[SceneObject, ...]: Selected container objects.
    """
    if isinstance(selection, SceneObject):
        return (selection,)
    if isinstance(selection, SceneObjectGroup):
        return selection.objects
    if isinstance(selection, tuple):
        return selection
    raise ValueError('container selector must select objects')

def recolor_cells(grid: Grid, cells: SceneCellGroup, color: int) -> Grid:
    """Return a copy of a grid with selected cells recolored.

    Args:
      grid (Grid): Input grid.
      cells (SceneCellGroup): Cells to recolor.
      color (int): New color.

    Returns:
      Grid: Recolored grid.
    """
    output = copy.deepcopy(grid)
    height, width = (len(grid), len(grid[0]))
    for row, col in cells.cells:
        if not (0 <= row < height and 0 <= col < width):
            raise ValueError('recolor_cells target is outside the grid')
        output[row][col] = color
    return output

def resolve_color_expression(color_expression: Any, grid: Grid) -> int:
    """Resolve a DSL color expression to an ARC color.

    Args:
      color_expression (Any): Integer color or color expression.
      grid (Grid): Input grid used for selector-derived colors.

    Returns:
      int: Resolved ARC color id.
    """
    if isinstance(color_expression, dict):
        op = color_expression.get('op')
        if op == 'selector_color':
            selector = color_expression.get('selector')
            if not isinstance(selector, dict):
                raise ValueError('selector_color requires a selector')
            return _selection_unique_color(select_scene_objects(selector, grid), grid)
        raise ValueError('Unknown DSL color expression: ' + str(op))
    return int(color_expression)

def _selection_unique_color(selection: SceneSelection, grid: Grid) -> int:
    """Return the unique visible color represented by a selection.

    Args:
      selection (SceneSelection): Selection to inspect.
      grid (Grid): Input grid.

    Returns:
      int: Unique selected color.
    """
    colors: set[int]
    if isinstance(selection, SceneObject):
        colors = {selection.color}
    elif isinstance(selection, SceneObjectGroup):
        colors = {obj.color for obj in selection.objects}
    elif isinstance(selection, SceneShapeInstance):
        colors = {selection.color}
    elif isinstance(selection, SceneShapeInstanceGroup):
        colors = {instance.color for instance in selection.instances}
    elif isinstance(selection, tuple):
        colors = {obj.color for obj in selection}
    elif isinstance(selection, SceneCell):
        colors = {grid[selection.row][selection.col]}
    elif isinstance(selection, SceneCellGroup):
        colors = {grid[row][col] for row, col in selection.cells}
    elif isinstance(selection, SceneCellPatch):
        colors = {color for _, _, color in selection.cells}
    else:
        raise ValueError('selector_color requires object or cell selection')
    if len(colors) != 1:
        raise ValueError('selector_color requires a unique selected color')
    return next(iter(colors))
